+ export interface GameApi {
+ /**
+ * 指定した種類のブロックをプレイヤーが通り抜けられるように設定する。
+ * 通常は固体で通り抜けられないブロックを通り抜ける時、内部にいる間わずかな視覚的な不具合が発生する。
+ *
+ * 通り抜けられないブロック(このAPIで指定したものも含む)の中にいて、かつ上にスペースがある場合、そのブロックの上に押し上げられる。
+ * この設定を解除(通り抜け不可に)して押し上げられることを防ぐには、設定解除前にブロックの破壊を。
+ *
+ * @param playerId - 設定対象のプレイヤー
+ * @param blockName - ブロックの名前
+ * @param disable - trueで設定を解除し,通常に戻す(通常が通り抜け可能の場合,通り抜け可能のまま)。通り抜け可能にする場合は指定の必要なし。
+ * @example
+ * // 草ブロックをすり抜け可能にする。
+ * api.setWalkThroughType(myId,"Grass Block");
+ *
+ * //草ブロックを通常通りすり抜け不可に戻す。
+ * api.setWalkThroughType(myId,"Grass Block",true);
+ */
+ setWalkThroughType(playerId: PlayerId, blockName: BlockName, disable?: boolean): void
+ }
+ export type EntityId = string
+ export type LifeformId = EntityId
+ export type PlayerId = LifeformId
+ export type BlockName = string
+ }}}
+ }}}}
